 function driverProfile(){return ops.drivers.find(d=>d.id===activeDriverId)||ops.drivers[0];}
 function driverPersonal(){if(activeDriverId==='DRV-1')return ops.personal;ops.driverProfiles||={};return ops.driverProfiles[activeDriverId]||=( {settings:{...D.defaults},offers:[],journeys:[]} );}
 function driverVehicle(){const d=driverProfile(),contract=K.contracts(ops,d.id).filter(c=>c.modelId==='rental'&&!['cancelled','refused'].includes(c.status)).at(-1);return M.vehicles(ops).find(v=>v.id===(d.vehicleId||d.nextVehicleId||contract?.vehicleId));}
 function driverOnboarding(){const d=driverProfile(),v=driverVehicle(),signed=K.hasSignedRental(ops,d.id,'2027-01-25',v?.id||null),inspected=v&&I.hasApprovedDelivery(ops,d.id,v.id);return panel('Sua contratação, passo a passo',`<ol class="onboarding-steps">${[['Cadastro e interesse',true],['Documentação conferida',d.docs],['Contrato concluído no exemplo',signed],['Vistoria de entrega aprovada',inspected],['Veículo entregue e aluguel ativo',d.stage==='active']].map(([label,done])=>`<li class="${done?'done':''}"><span>${done?'✓':'○'}</span>${label}</li>`).join('')}</ol>`+row('Etapa atual',M.stages.find(([k])=>k===d.stage)[1])+row('Próximo passo',esc(d.note||'Aguardar orientação da gestão.'))+row('Veículo previsto',esc(v?.model||'Aguardando disponibilidade'))+`<div class="actions gap">${btn('Meus contratos','driver-docs')}${btn('Minha vistoria','driver-inspection')}${btn('Meus compromissos','driver-agenda')}</div>`);}
 function driverDocumentsView(){const docs=K.driverDocuments(ops,activeDriverId);return panel('Meus contratos e termos',docs.length?docs.map(c=>`<article class="driver-document"><h3>${esc(c.title)}</h3><p class="caption">${esc(c.id)} · documento v${c.version} · modelo v${c.modelVersion}</p>${row('Situação',tag(c.statusLabel,c.status==='signed'?'green':'amber'))}${row('Motorista',c.driverRecorded?'Registro demonstrativo concluído':'Aguardando registro')}${row('Locadora',c.companyRecorded?'Registro demonstrativo concluído':'Aguardando registro')}${row('Vigência',date(c.startDate)+' a '+date(c.endDate))}<div class="actions">${btn('Ler documento','driver-doc-preview','',`data-id="${c.id}"`)}${['awaiting','partial'].includes(c.status)&&!c.driverRecorded?btn('Simular meu registro de assinatura','driver-doc-sign','primary',`data-id="${c.id}"`):''}</div></article>`).join(''):'<p class="caption">Ainda não há documento preparado para este perfil. A locadora organizará os modelos e a fila em Meu advogado.</p>')+'<div class="notice amber gap">Prévia e registros de assinatura são demonstrativos. Nenhum documento é assinado ou enviado por esta página.</div>';}
 function driverAgendaView(){const entries=K.agendaItems(ops).filter(e=>e.driverId===activeDriverId&&e.status!=='cancelled');return panel('Meus compromissos',entries.length?entries.map(e=>row(esc(e.title),date(e.date)+' · '+esc(e.time),esc(e.note||'')+(e.status==='done'?' · Concluído':' · Pendente'))).join(''):'<p class="caption">Nenhum compromisso registrado para este perfil.</p>')+'<p class="caption">Lembretes são exibidos com o aplicativo aberto; push, WhatsApp e e-mail ainda não estão conectados.</p>';}
 const driverNames={home:'Início',ride:'Vale a corrida?',journey:'Minha jornada',wallet:'Carteira',shop:'Minha loja',more:'Mais',care:'Meu carro e manutenção',inspection:'Vistoria',docs:'Contrato e documentos',support:'Suporte',goals:'Metas e custos',onboarding:'Minha contratação',agenda:'Meus compromissos',benefits:'Benefícios RODAVOLT'};
 function driverView(){const profile=driverProfile();return heading('RODAVOLT MOTORISTA','Mais controle de quem está ao volante.','Um espaço para decidir melhor, cuidar do carro e acompanhar cada compromisso.')+`<div class="driver-profile">${select('driverProfile','Perfil de demonstração',activeDriverId,ops.drivers.map(d=>[d.id,d.name]),'data-driver-profile="true"')}<p class="caption">Troca de perfil apenas para avaliar o fluxo. A aplicação operacional terá login e permissões por vínculo.</p></div><div class="driver-layout"><section class="mobile-app" aria-label="Aplicativo do motorista"><div class="mobile-brand"><span>RODAVOLT MOTORISTA</span><span class="avatar">${initials(profile.name)}</span></div><h2>${driverPage==='home'?'Olá, '+esc(profile.name.split(' ')[0])+'.':driverNames[driverPage]}</h2><p class="mobile-subtitle">${driverPage==='home'?'Seu dia pode começar com um plano.':esc((profile.vehicleId||profile.nextVehicleId||'Aguardando carro')+' · perfil demonstrativo')}</p><div id="driver-body">${driverBody()}</div><nav class="driver-tabs" aria-label="Navegação do motorista">${[['home','Início'],['ride','Corrida'],['wallet','Carteira'],['shop','Loja'],['more','Mais']].map(([key,label])=>`<button type="button" data-driver-page="${key}" aria-pressed="${key===driverPage||(key==='more'&&['care','inspection','docs','support','goals','journey','onboarding','agenda','benefits'].includes(driverPage))}">${label}</button>`).join('')}</nav></section><aside class="driver-context"><span class="eyebrow">DO SEU OBJETIVO À SUA DECISÃO</span><h2>Ganhar bem começa<br>por entender a conta.</h2><p>A oferta precisa pagar o trajeto completo, seu tempo e os custos de rodar. Aqui o motorista compara com suas metas, decide e registra — sem misturar seus ganhos pessoais com o caixa da locadora.</p><div class="driver-menu">${[['ride','Vale a corrida?','R$/km, ganho por hora e oferta mínima'],['goals','Metas e custos','Objetivo diário, combustível e aluguel'],['journey','Minha jornada','Ganhos, despesas e km por dia'],['wallet','Carteira','Aluguel, comprovantes e repasses'],['care','Meu carro','Revisão, km e pedidos de manutenção'],['inspection','Vistoria','Checklist, hodômetro e observações'],['shop','Minha loja','Perfumes, acessórios e margem'],['benefits','Benefícios RODAVOLT','Loja, crédito semanal e próximos aplicativos'],['onboarding','Minha contratação','Cadastro, assinatura, vistoria e entrega'],['agenda','Meus compromissos','Datas, cobranças e entregas'],['docs','Meus documentos','Contrato, condições e termos'],['support','Suporte','Pedidos e respostas no histórico']].map(([key,title,desc])=>`<button type="button" data-driver-page="${key}" aria-pressed="${driverPage===key}">${title}<small>${desc}</small></button>`).join('')}</div><div class="notice gap">A análise de corrida é manual e considera os valores informados pelo motorista. Não lê a tela nem aceita ou recusa corridas no Uber/99. Use antes de iniciar o deslocamento.</div></aside></div>`;}
 function driverBody(){const profile=driverProfile(),vehicle=driverVehicle(),p=driverPersonal().settings,personal=D.daySummary(driverPersonal().journeys,p),s=activeDriverId==='DRV-1'?M.shopSummary(ops):{commission:0,remittance:0,payable:0,sales:0},charge=ops.charges.find(c=>c.driverId===activeDriverId&&c.status!=='paid');
 if(driverPage==='benefits')return driverBenefits();
 if(driverPage==='onboarding')return driverOnboarding();
 if(driverPage==='agenda')return driverAgendaView();
 if(driverPage==='inspection')return driverInspection();
 if(driverPage==='docs')return driverDocumentsView();
 if(driverPage==='care'&&!vehicle)return panel('Seu veículo','<p class="caption">Aguardando a locadora definir o veículo para entrega.</p>')+driverOnboarding();
 if(driverPage==='shop'&&(activeDriverId!=='DRV-1'||profile.stage!=='active'))return panel('Kit comercial ainda não entregue','<p class="caption">O estoque será disponibilizado depois da entrega do carro e do termo de custódia. Este protótipo possui um kit demonstrativo vinculado ao RV-001.</p>');
 if(driverPage==='home')return (profile.stage!=='active'?driverOnboarding()+'<div class="gap"></div>':'')+`<div class="personal-summary"><small>SUA META DE GANHO LÍQUIDO POR DIA</small><strong>${money(p.goalDay)}</strong><small>Depois de combustível, outras despesas e aluguel rateado.</small></div><div class="quick-grid"><button type="button" data-driver-page="ride">Vale a corrida?<small>Compare a oferta com sua meta</small></button><button type="button" data-driver-page="journey">Fechar minha jornada<small>Ganhos, despesas e km do dia</small></button><button type="button" data-driver-page="wallet">Meu aluguel<small>${charge?money(charge.amount)+' · '+date(charge.date):ops.charges.some(c=>c.driverId===activeDriverId)?'Cobranças conferidas':'Sem cobrança emitida'}</small></button><button type="button" data-driver-page="shop">Vender na minha loja<small>Perfumes e acessórios</small></button></div><div class="gap">${panel('Seu resumo pessoal',row('Jornadas registradas',personal.days+' dia(s)')+row('Saldo após aluguel rateado',cash(personal.net),'Somente os dias que você registrou.')+row('Lucro da lojinha a conferir',cash(s.commission))+row('Crédito disponível',cash(R.driverCredits(ops,activeDriverId).available))+btn('Ver benefícios e crédito da loja','driver-benefits')+link('Ajustar minhas metas e custos →','driver-goals'))}</div><div class="gap">${panel('Cuidado com seu carro',row('Próxima revisão',num(vehicle?Math.max(0,vehicle.nextKm-vehicle.km):null)+' km',vehicle?'Hodômetro informado: '+num(vehicle.km)+' km.':'Aguardando veículo previsto.')+btn('Pedir manutenção','driver-care'))}</div>`;
 if(driverPage==='ride')return rideView();
 if(driverPage==='goals')return `<form id="goals-form"><div class="fields">${Object.entries({goalDay:'Meta líquida por dia · R$',minNetKm:'Mínimo líquido por km · R$',minNetHour:'Mínimo líquido por hora · R$',fuelPrice:'Combustível por litro · R$',efficiency:'Consumo médio · km/l',otherPerKm:'Outros custos seus por km · R$',weeklyRent:'Aluguel semanal · R$',workDays:'Dias trabalhados por semana',hoursDay:'Horas planejadas por dia',plannedKmDay:'Km planejados por dia'}).map(([key,label])=>input(key,label,p[key],`type="number" min="${D.limits[key][0]}" max="${D.limits[key][1]}" step="${key==='workDays'?'1':'any'}" required`)).join('')}</div><div class="form-actions"><button type="submit" class="btn primary">Salvar minhas metas</button></div><p class="caption">Inclua em “outros custos” somente os que você paga, para não duplicar custos já cobertos pelo aluguel. O valor da oferta deve ser o que você receberá, sem descontar a taxa do app outra vez.</p></form>`;
 if(driverPage==='journey')return `<div class="personal-summary"><small>SALDO DOS DIAS REGISTRADOS</small><strong>${cash(personal.net)}</strong><small>Recebido − combustível − outras despesas − aluguel rateado.</small></div>${panel('Fechar ou corrigir um dia',`<form id="journey-form"><div class="fields">${input('date','Dia da jornada','2027-01-25','type="date" required')}${input('amount','Ganhos recebidos · R$',400,'type="number" min="0" step=".01" required')}${input('fuel','Combustível pago · R$',85,'type="number" min="0" step=".01" required')}${input('other','Outras despesas · R$',15,'type="number" min="0" step=".01" required')}${input('km','Km totais rodados',180,'type="number" min="0" step="any" required')}${input('hours','Horas trabalhadas',8,'type="number" min="0" max="24" step="any" required')}</div><div class="form-actions"><button type="submit" class="btn primary">Salvar fechamento do dia</button></div><p class="caption">Salvar de novo a mesma data corrige o registro. O aluguel é rateado uma vez por dia, sem duplicar.</p></form>`)}<div class="gap">${panel('Meus resultados',row('Recebido',cash(personal.amount))+row('Combustível e outras despesas',cash(personal.fuel+personal.other))+row('Aluguel rateado',cash(personal.rent))+row('Saldo líquido',cash(personal.net),'',true)+row('Líquido por km',personal.netKm===null?'Sem jornada':cash(personal.netKm))+row('Líquido por hora',personal.netHour===null?'Sem jornada':cash(personal.netHour)))}</div><div class="gap">${panel('Histórico pessoal',driverPersonal().journeys.length?driverPersonal().journeys.map(j=>row(date(j.date),cash(D.daySummary([j],p).net),num(j.km)+' km · '+num(j.hours)+' horas')).join(''):'<p class="caption">Nenhum dia registrado ainda. Sua jornada não entra como receita da locadora.</p>')}</div>`;
 if(driverPage==='wallet')return `${panel('Seu aluguel semanal',ops.charges.filter(c=>c.driverId===activeDriverId).map(c=>row(c.id+' · '+date(c.date),cash(R.currentChargeBalance(ops,c)),(c.creditApplied?'Original '+cash(c.amount)+' · abatido '+cash(c.creditApplied)+' · ':'')+(c.status==='paid'?'Recebimento conferido':ops.proofs.some(pr=>pr.chargeId===c.id&&pr.status==='pending')?'Comprovante em análise':'Em aberto'))).join('')+(charge&&!ops.proofs.some(pr=>pr.chargeId===charge.id&&pr.status==='pending')?btn('Enviar comprovante de exemplo','proof','primary',`data-id="${charge.id}"`):''))}<div class="gap">${panel('Lucro da lojinha e abatimento',row('Lucro das vendas em acerto',cash(s.commission))+row('Custo a repassar',cash(s.remittance),'Se você já ficou com a margem em dinheiro. Para crédito, o bruto precisa estar conferido na empresa.')+row('Margem a receber da empresa',cash(s.payable),'Escolha receber ou gerar crédito; sem repetir o benefício.')+programCredits(activeDriverId,true)+row('Caução','Conforme contrato','Não é receita nem saldo livre para descontar.')+btn('Ver meus contratos','driver-docs'))}</div><p class="caption">Comprovante ilustrativo: sem Pix nem upload real. A gestão precisa conferir para confirmar o recebimento.</p>`;
 if(driverPage==='shop')return `${panel('Seu kit, com preço e estoque',ops.book.products.map(p=>row(esc(p.name),cash(p.price),p.kit+' un. no carro · custo e sua margem preservados por venda.')).join(''))}<div class="gap">${panel('Vender um produto',saleForm())}</div><div class="gap">${panel('Lucro e reposição',row('Lucro da lojinha a conferir',cash(s.commission))+row('Crédito disponível',cash(R.driverCredits(ops,activeDriverId).available))+btn('Ver benefícios e crédito da loja','driver-benefits')+row('Vendas abertas',String(s.sales))+`<form id="stock-request-form"><div class="fields">${select('productId','Produto para repor','perfume',ops.book.products.map(p=>[p.id,p.name]))}${input('qty','Quantidade',2,'type="number" min="1" step="1" required')}</div><div class="form-actions"><button type="submit" class="btn">Pedir reposição</button></div></form>`)}</div>`;
 if(driverPage==='care')return `${panel(esc(vehicle.id+' · '+vehicle.model),row('Hodômetro',num(vehicle?.km)+' km')+row('Próxima preventiva',num(vehicle.nextKm)+' km')+row('Situação',vehicle.status==='maintenance'?'Em manutenção':'Vínculo ativo de exemplo')+btn('Fazer vistoria','driver-inspection'))}<div class="gap">${panel('Pedir manutenção',`<form id="maintenance-request-form">${select('priority','Impacto para trabalhar','normal',[['normal','Carro rodando · avaliar serviço'],['urgent','Carro parado · atendimento prioritário']])}<label class="field gap">Descreva o problema<textarea name="note" required rows="3" maxlength="500" placeholder="O que aconteceu e quando começou?"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Abrir solicitação</button></div></form>`)}</div><div class="gap">${panel('Acompanhar pedidos',driverRequests('maintenance'))}</div>`;
 if(driverPage==='support')return `${panel('Conversar com a RODAVOLT',`<form id="support-form">${select('subject','Assunto','Contrato',[['Contrato','Contrato'],['Pagamento','Pagamento'],['Loja','Loja'],['Carro','Carro']])}<label class="field gap">Sua mensagem<textarea name="note" required rows="3" maxlength="500"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Registrar chamado</button></div></form>`)}<div class="gap">${panel('Meus protocolos',driverRequests('support'))}</div>`;
 return `<div class="quick-grid">${[['benefits','Benefícios RODAVOLT'],['onboarding','Minha contratação'],['agenda','Meus compromissos'],['goals','Metas e custos'],['journey','Minha jornada'],['care','Meu carro e manutenção'],['inspection','Vistoria'],['docs','Contrato e documentos'],['support','Suporte']].map(([key,title])=>`<button type="button" data-driver-page="${key}">${title}<small>Abrir →</small></button>`).join('')}</div><p class="caption">Dados pessoais da jornada separados dos recebimentos da empresa. Esta demonstração não substitui autenticação e permissões individuais no servidor.</p>`;
 }
 function driverRequests(type){const list=ops.requests.filter(r=>r.type===type&&(r.driverId||'DRV-1')===activeDriverId);return list.length?list.map(r=>row(r.id,tag(r.status==='open'?'Aberto':r.status==='answered'?'Respondido':r.status==='delivered'?'Entregue':'Em atendimento',r.status==='open'?'amber':'green'),esc(r.note))+(r.reply?`<div class="notice gap"><strong>Resposta no exemplo</strong><br>${esc(r.reply)}</div>`:'')).join(''):'<p class="caption">Ainda sem solicitações desse tipo.</p>';}
 function rideView(){rideResult=D.evaluate(ride,driverPersonal().settings);return `<div class="notice">A oferta deve ser o valor que você receberá. A distância inclui o caminho até o passageiro e eventual reposicionamento.</div><form id="ride-form" class="gap"><div class="fields">${input('amount','Valor líquido da oferta · R$',ride.amount,'type="number" min="0" step=".01" required')}${input('tripKm','Km com passageiro',ride.tripKm,'type="number" min="0" step="any" required')}${input('pickupKm','Km até o passageiro',ride.pickupKm,'type="number" min="0" step="any" required')}${input('tripMin','Minutos da viagem',ride.tripMin,'type="number" min="0" step="any" required')}${input('pickupMin','Minutos até o passageiro',ride.pickupMin,'type="number" min="0" step="any" required')}${input('toll','Pedágio não reembolsado · R$',ride.toll,'type="number" min="0" step=".01" required')}</div><details><summary>Espera e reposicionamento após a viagem</summary><div class="fields">${input('waitMin','Minutos de espera',ride.waitMin,'type="number" min="0" step="any" required')}${input('returnKm','Km de retorno/reposição',ride.returnKm,'type="number" min="0" step="any" required')}${input('returnMin','Minutos de retorno/reposição',ride.returnMin,'type="number" min="0" step="any" required')}</div></details><p id="ride-error" class="form-error" role="alert" hidden></p></form><div id="ride-result" aria-live="polite">${rideResultBody()}</div><div class="actions gap">${btn('Registrar que aceitei','accept-ride','primary')}${btn('Registrar que recusei','reject-ride')}</div><p class="caption">Os botões só registram sua decisão nesta demonstração. Não enviam nenhuma ação para aplicativos de corrida.</p>${link('Ajustar minhas metas, consumo e custos →','driver-goals')}<details><summary>Minhas decisões registradas (${driverPersonal().offers.length})</summary>${driverPersonal().offers.slice().reverse().map(o=>row(o.choice==='accepted'?'Aceitei':'Recusei',cash(o.amount),cash(o.netKm)+'/km líquido · '+cash(o.netHour)+'/h · '+(o.meets?'atingia as metas':'abaixo das metas'))).join('')||'<p class="caption">Ainda sem decisão registrada.</p>'}</details>`;}
 function rideResultBody(){const r=rideResult;if(!r)return '<div class="notice amber">Revise os campos para calcular. Informe tempo e distância maiores que zero.</div>';return `<section class="ride-result ${r.meets?'':'negative'}"><p class="result-word">${r.meets?'Essa oferta atinge suas metas.':'Essa oferta fica abaixo das suas metas.'}</p><div class="ride-metrics"><div><strong>${cash(r.netKm)}</strong><small>POR KM LÍQUIDO · META ${cash(Math.max(r.p.minNetKm,r.goalKm))}</small></div><div><strong>${money(r.netHour)}</strong><small>POR HORA LÍQUIDA · META ${money(Math.max(r.p.minNetHour,r.goalHour))}</small></div></div><p class="caption">${num(r.km)} km totais · ${num(r.minutes)} minutos totais. ${r.meets?'Você decide se faz sentido para este momento.':r.reasons.map(esc).join(' · ')+'.'}</p></section><div class="gap">${panel('A conta da corrida',row('Oferta que você receberá',cash(r.o.amount))+row('Combustível estimado',cash(-r.fuel))+row('Outros custos por km',cash(-r.variable))+row('Aluguel rateado pelo tempo',cash(-r.rent))+row('Pedágio não reembolsado',cash(-r.o.toll))+row('Sobra líquida estimada',cash(r.net),'Após os custos acima; depende das premissas.',true)+row('Oferta mínima para suas metas',cash(r.minimumOffer),'O maior requisito entre R$/km, R$/h e meta diária convertida por km e tempo.')+row('Falta na oferta atual',cash(r.gap)))}</div>`;}
 function updateRide(){const form=root.querySelector('#ride-form');if(!form)return;const values=Object.fromEntries(new FormData(form));for(const key of Object.keys(values))values[key]=Number(values[key]);try{const calculated=D.evaluate(values,driverPersonal().settings);ride=values;rideResult=calculated;root.querySelector('#ride-error').hidden=true;}catch(error){rideResult=null;const element=root.querySelector('#ride-error');element.hidden=false;element.textContent=error.message;}root.querySelector('#ride-result').innerHTML=rideResultBody();}
 function driverAction(action,e){if(action.startsWith('driver-')&&driverNames[action.slice(7)]){driverPage=action.slice(7);mode='driver';close();render();persist();return true;}
 if(action==='accept-ride'||action==='reject-ride'){updateRide();if(!rideResult)throw new RangeError('Revise a oferta antes de registrar a decisão.');driverPersonal().offers.push({at:new Date().toISOString(),...ride,choice:action==='accept-ride'?'accepted':'rejected',net:rideResult.net,netKm:rideResult.netKm,netHour:rideResult.netHour,meets:rideResult.meets});render();persist();toast('Decisão registrada só no seu histórico pessoal.');return true;}
 if(action==='driver-doc-preview'){const doc=K.driverDocuments(ops,activeDriverId).find(c=>c.id===e.dataset.id);if(!doc)throw new RangeError('Documento não pertence a este perfil.');open(doc.title,`<p class="notice amber">Rascunho demonstrativo · sujeito a revisão jurídica.</p><pre class="document-preview">${esc(doc.preview)}</pre>`);return true;}
 if(action==='driver-doc-sign'){const doc=K.driverDocuments(ops,activeDriverId).find(c=>c.id===e.dataset.id);if(!doc)throw new RangeError('Documento não pertence a este perfil.');K.recordSignature(ops,doc.id,'driver');render();persist();toast('Registro de signatário simulado. Nenhuma assinatura real foi executada.');return true;}
 if(action==='proof'){if(!ops.charges.some(c=>c.id===e.dataset.id&&c.driverId===activeDriverId))throw new RangeError('Cobrança fora do perfil.');M.proof(ops,e.dataset.id,'Envio ilustrativo pelo motorista · '+e.dataset.id);render();persist();toast('Comprovante em análise. O aluguel só baixa depois da conferência.');return true;}return false;}
 function driverSubmit(form,f){const n=key=>Number(f.get(key));let handled=true;
 if(form.id==='goals-form'){const next={};for(const key of Object.keys(D.defaults))next[key]=n(key);driverPersonal().settings=D.validate(next);rideResult=D.evaluate(ride,next);}
 else if(form.id==='journey-form'){M.saveJourney({personal:driverPersonal()},{date:String(f.get('date')),amount:n('amount'),fuel:n('fuel'),other:n('other'),km:n('km'),hours:n('hours')});}
 else if(form.id==='maintenance-request-form'){M.request(ops,{type:'maintenance',driverId:activeDriverId,vehicleId:driverVehicle()?.id,priority:f.get('priority'),note:f.get('note')});}
 else if(form.id==='stock-request-form'){const productId=f.get('productId'),p=ops.book.products.find(p=>p.id===productId);M.request(ops,{type:'stock',driverId:activeDriverId,vehicleId:driverVehicle()?.id,productId,qty:n('qty'),note:'Reposição de '+n('qty')+' × '+p.name});}
 else if(form.id==='inspection-form'){M.inspect(ops,{km:n('km'),note:f.get('note'),checks:[0,1,2,3].map(i=>f.has('check'+i))});}
 else if(form.id==='support-form'){M.request(ops,{type:'support',driverId:activeDriverId,vehicleId:driverVehicle()?.id,subject:f.get('subject'),note:f.get('note')});}
 else handled=false;if(handled){render();persist();toast('Registro salvo na sua área de demonstração.');}return handled;}
